import androidx.compose.ui.graphics.PathFillType

// Drawn HUD icons. Every icon is vector shapes in a 100 x h box, drawn in code (no image files, no emojis).
// Colour slots: 0 main, 1 accent, 2 dim, 3 cut (button fill), 4 gold, 5 cyan, 6 red, 7 blue, 8 dark gold, 9 dark cyan, 10 soft white.

enum class Glyph(val h: Float) {
    BULLET(100f),
    JUMP(100f),
    CROUCH(100f),
    PRONE(100f),
    SHIELD(100f),
    SPRINT(100f),
    BACKPACK(100f),
    MEDKIT(100f),
    GRENADE(100f),
    SYMMETRY(100f),
    FIST(100f),
    SWITCH(100f),
    CHEVRON(100f),
    SWORDS(100f),
    MIC_OFF(100f),
    SPK_OFF(100f),
    EMOJI(100f),
    CHAT(100f),
    PLAYERS(100f),
    SKULL(100f),
    GEAR(100f),
    COIN(100f),
    GEM(100f),
    HELMET(100f),
    ARMOR(100f),
    WOLF(100f),
    RIFLE(40f),
    PISTOL(70f),

    // added for the main menu
    STORE(100f),
    LUCK(100f),
    CHARACTER(100f),
    VAULT(100f),
    MISSIONS(100f),
    EVENTS(100f),
    CROWN(100f),
    PRESET(100f),
    LAB(100f),
    INVENTORY(100f),
    RANKBADGE(100f),
    MEMBER(100f),
    GIFT(100f),
    MAIL(100f),
    WIFI(100f),
    BATTERY(100f),
    CLOCK(100f),
    CUBE(100f)
}

private class GShape(val c: Int, val contours: List<FloatArray>, val dot: FloatArray?)

private fun parseShapes(src: String): List<GShape> =
    src.split(';').filter { it.isNotEmpty() }.map { sh ->
        val colon = sh.indexOf(':')
        val c = sh.substring(1, colon).toInt()
        val body = sh.substring(colon + 1)
        if (sh[0] == 'D') {
            GShape(c, emptyList(), body.split(',').map { it.toFloat() }.toFloatArray())
        } else {
            GShape(
                c,
                body.split('|').map { ct ->
                    ct.trim().split(' ').flatMap { pt -> pt.split(',') }.map { it.toFloat() }.toFloatArray()
                },
                null
            )
        }
    }

private val shapeCache = HashMap<Glyph, List<GShape>>()

private fun shapesOf(g: Glyph): List<GShape> =
    shapeCache.getOrPut(g) { parseShapes(glyphData(g)) }

/** Draws a glyph so its 100-unit width fills the modifier width; height follows the glyph's own ratio. */
@Composable
fun GlyphIcon(
    g: Glyph,
    modifier: Modifier,
    main: Color = Color.White,
    accent: Color = Color(0xFFFF8A00),
    cut: Color = Color(0xFF0A1230)
) {
    val shapes = shapesOf(g)
    Canvas(modifier) {
        val s = size.width / 100f
        val oy = (size.height - g.h * s) / 2f
        val pal = arrayOf(
            main, accent, main.copy(alpha = main.alpha * 0.4f), cut,
            Color(0xFFFFC21A), Color(0xFF35D3FF), Color(0xFFE5483C), Color(0xFF2D8CFF),
            Color(0xFFB87800), Color(0xFF1E88D8), Color(0x8CFFFFFF)
        )
        for (sh in shapes) {
            val color = pal[sh.c]
            val dot = sh.dot
            if (dot != null) {
                drawCircle(color, dot[2] * s, Offset(dot[0] * s, oy + dot[1] * s))
            } else {
                val path = Path().apply {
                    fillType = PathFillType.EvenOdd
                    for (ct in sh.contours) {
                        moveTo(ct[0] * s, oy + ct[1] * s)
                        var i = 2
                        while (i + 1 < ct.size) {
                            lineTo(ct[i] * s, oy + ct[i + 1] * s)
                            i += 2
                        }
                        close()
                    }
                }
                drawPath(path, color)
            }
        }
    }
}

